import{_ as e,o as t,c as a,ag as i}from"./chunks/framework.BbSdnUwJ.js";const k=JSON.parse('{"title":"Command line","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),n={name:"reference/cli.md"};function o(d,s,r,l,h,p){return t(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="command-line" tabindex="-1">Command line <a class="header-anchor" href="#command-line" aria-label="Permalink to &quot;Command line&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mobiledsl compile FILE... [--library DIR]... [--check] [--target NAME] [--output DIR]</span></span>
<span class="line"><span>                  [--warnings-as-errors] [--json] [--color auto|always|never]</span></span>
<span class="line"><span>mobiledsl --version</span></span></code></pre></div><p>A program is given as files: one <code>.core</code>, one <code>.world</code>, one <code>.task</code>, and optionally one <code>.eval</code>, in any order. The extension says which form a file is. There is no project file: the libraries, the target, and the output directory are settings of the compile, not of the program.</p><table tabindex="0"><thead><tr><th>Option</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--library DIR</code>, <code>-l DIR</code></td><td>A component library; repeat for several. A part must be in exactly one of them.</td></tr><tr><td><code>--check</code></td><td>Stop after validation and emit nothing.</td></tr><tr><td><code>--target NAME</code>, <code>-t NAME</code></td><td>The target to emit: <code>ros-gz-nav2</code> or <code>ros-mujoco-nav2</code>. Needs <code>--output</code>.</td></tr><tr><td><code>--output DIR</code>, <code>-o DIR</code></td><td>The directory the target writes. It is created if missing; a file of the same name is replaced, never written through a link, and other files are left alone. It must not be, hold, or sit inside a source file or a library, and no directory in it may be a symbolic link.</td></tr><tr><td><code>--warnings-as-errors</code></td><td>A warning blocks compilation from where it is found, so nothing is written; each affected diagnostic says so in a <code>note</code>.</td></tr><tr><td><code>--json</code></td><td>Write the structured result to stdout.</td></tr><tr><td><code>--color</code></td><td><code>auto</code> colors when stderr is a terminal and neither <code>NO_COLOR</code> nor <code>TERM=dumb</code> is set; <code>always</code> and <code>never</code> override.</td></tr></tbody></table><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><p>Diagnostics and one summary line go to stderr, in the form specified in <a href="./diagnostics.html">Diagnostics</a>. A clean check ends with <code>Checked demo.core demo.world demo.task (9 checks)</code>, counting the validation rules that applied; a check that left a rule undecided says <code>(9 checks, 1 undecided)</code>; a compile ends with <code>Compiled demo.core demo.world demo.task (9 checks) into build (31 files)</code>; a failure ends with <code>error: 1 error; ... did not compile</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error[name.unknown_component_type]: unknown component type &#39;Lidra&#39;</span></span>
<span class="line"><span>   --&gt; demo.core:12:5</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>12 |     Lidra top_lidar(ref = &quot;lidar_ld06&quot;, glue = (0, 0.0001, 0.0344, 0, 0, -1))</span></span>
<span class="line"><span>   |     ^^^^^ not a component type</span></span>
<span class="line"><span>   |</span></span>
<span class="line"><span>   = help: did you mean &#39;Lidar&#39;?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>error: 1 error; demo.core demo.world demo.task did not compile</span></span></code></pre></div><p>With <code>--json</code>, stdout holds one document:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;robotdsl.compile&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sources&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;demo.core&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;demo.world&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;demo.task&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;phases&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;source_load&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pass&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;library_load&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pass&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;parse&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pass&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;diagnostics&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;validation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;rule&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;assembly.glue_on_connector&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pass&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;evidence&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>When a target was written, the document also has <code>output</code> (the directory and the files written, <code>compile.json</code> included) and <code>approximations</code> (what the target stood in for, see the <a href="./output.html">output contract</a>).</p><p><code>phases</code> names every compiler phase with <code>pass</code>, <code>invalid</code>, <code>environment_failed</code>, <code>not_run</code> (an earlier phase failed) or <code>not_requested</code> (<code>--check</code> stopped before it). <code>diagnostics</code> is the same list the terminal shows, in the JSON form. <code>validation</code> has one entry per rule with its status and evidence, including rules that were <code>not_applicable</code>.</p><h2 id="exit-status" tabindex="-1">Exit status <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;Exit status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>0</td><td>Nothing blocked. Warnings may have been printed.</td></tr><tr><td>1</td><td>A diagnostic blocked: a problem in the program or a library, a missing file, an unknown target, or a warning under <code>--warnings-as-errors</code>.</td></tr><tr><td>2</td><td>The command line itself was wrong.</td></tr></tbody></table><h2 id="what-a-clean-check-does-not-establish" tabindex="-1">What a clean check does not establish <a class="header-anchor" href="#what-a-clean-check-does-not-establish" aria-label="Permalink to &quot;What a clean check does not establish&quot;">​</a></h2><p>A clean check means the program names existing parts, every argument is well typed, every reference resolves, the assembly mates onto real connectors, and the standard rules pass on the facts the library states. It does not establish that the robot spawns, drives, or completes the task: those are observed when the emitted target runs, and the target reports them.</p>`,15)])])}const u=e(n,[["render",o]]);export{k as __pageData,u as default};
